package com.chromebrothers.navegador.regras

/** Manual do motor de pincéis (ler_manual topico=pinceis): o que a IA precisa para criar pincéis bons. */
object ManualDePinceisDoAgenteDoChat {
    fun texto(): String = buildString {
        appendLine("Manual de pincéis do editor de imagem (ferramentas: listar_pinceis, ler_pincel, criar_pincel, ajustar_pincel, testar_pincel, usar_pincel, usar_imagem_como_ponta).")
        appendLine()
        appendLine("COMO O MOTOR FUNCIONA")
        appendLine("O traço é feito carimbando a FORMA (ponta) várias vezes ao longo do caminho. Cada carimbo pode variar de tamanho, opacidade, rotação e posição. A opacidade escolhida pelo usuário é o teto do traço inteiro; o fluxo é a tinta de cada carimbo, que acumula até esse teto.")
        appendLine("O tamanho e a opacidade vêm do controle da barra lateral, presos aos limites mínimo/máximo do pincel; a pressão da caneta (já passada pela curva de pressão do usuário) e a velocidade modulam por cima. Pressão normal ≈ 40%: nela o pincel tem o tamanho escolhido; apertar engrossa, aliviar afina.")
        appendLine()
        appendLine("PARÂMETROS (faixa — efeito)")
        appendLine("Forma: ponta (id de ponta pronta, abaixo) OU forma REDONDA/QUADRADA/RUIDOSA. dureza 0..1 (só REDONDA/RUIDOSA): 0 borda bem macia (aerógrafo), 1 borda dura. proporcao 0.05..1: 1 redondo, baixo = achatado (ponta de caligrafia). anguloFixo -180..180: inclinação da ponta. seguirTraco true: a ponta gira com a direção (cerdas, fita, caligrafia que acompanha).")
        appendLine("Traço: espacamento 0.01..2 (fração do diâmetro entre carimbos): 0.02–0.06 contínuo e liso; 0.1–0.2 texturizado; ≥0.5 carimbos separados (respingos, estampas). fluxo 0.01..1: baixo = transparente que acumula (aerógrafo 0.05–0.15, aquarela 0.2–0.3); alto = sólido. dispersao 0..2: espalha carimbos para os lados (giz 0.05–0.1, spray 0.5+).")
        appendLine("Variação: tremorDeTamanho 0..1, tremorDeOpacidade 0..1, tremorDeRotacao 0..1 (1 = qualquer ângulo; use em pontas texturizadas para não repetir o desenho).")
        appendLine("Afinamento: afinamentoInicio/afinamentoFim 0..1 (comprimento da ponta fina no começo/fim; nanquim 0.5/0.6, caligrafia 0.25/0.35).")
        appendLine("Pressão: pressaoNoTamanho 0..1 (quanto a força muda a espessura; nanquim 0.7–0.9), pressaoNaOpacidade 0..1 (lápis/aerógrafo 0.6–0.8). Velocidade: velocidadeNoTamanho/velocidadeNaOpacidade 0..1 (traço rápido afina/clareia, efeito de pincel de verdade).")
        appendLine("Tamanho: multiplicadorDeLargura 0.1..6 (diâmetro relativo; fino 0.4–0.6, médio 1–1.6, largo 2–3.5). tamanhoMinimo/tamanhoMaximo e opacidadeMinima/opacidadeMaxima 0..1: limites do controle.")
        appendLine("Estabilização: streamline 0..1 (o traço segue a ponta com atraso suave; caligrafia/lettering 0.2–0.4; desenho solto 0–0.1).")
        appendLine("Textura (granulado): granulado NENHUM/PAPEL/TELA (ou imagem via usar_imagem_como_ponta como=granulado); granuladoFixoNoPapel true = a textura fica parada na folha (giz/lápis em papel áspero), false = anda com cada carimbo; escalaDoGranulado 0.1..8; intensidadeDoGranulado 0..1.")
        appendLine()
        appendLine("PONTAS PRONTAS (ponta=id)")
        appendLine(PontasProntasDoMotor.TODAS.joinToString("; ") { "${it.id} (${it.nome})" } + ".")
        appendLine("Dicas: lapis/carvao/giz-pastel/esponja/aquarela/nevoa ficam melhores com tremorDeRotacao 1. cerdas/pincel-seco são uma coluna de pontinhos: use seguirTraco true e espacamento 0.02–0.03 (cada ponto vira um fio). chanfrado/tinteiro são chatos: use anguloFixo 30–45 e seguirTraco false (engrossa/afina conforme a direção). respingos: espacamento 0.7–1, dispersao 0.4–0.8, tremorDeTamanho 0.5+. hachura: espacamento 0.3+.")
        appendLine()
        appendLine("RECEITAS (ponto de partida)")
        appendLine("- Nanquim fino: forma REDONDA, dureza 1, espacamento 0.04, afinamentoInicio 0.5, afinamentoFim 0.6, pressaoNoTamanho 0.8, multiplicadorDeLargura 0.55, streamline 0.3.")
        appendLine("- Lápis: ponta lapis, espacamento 0.06, tremorDeRotacao 1, fluxo 0.85, pressaoNaOpacidade 0.75, pressaoNoTamanho 0.35, multiplicadorDeLargura 0.5, granulado PAPEL 0.45 fixo no papel.")
        appendLine("- Aquarela: ponta aquarela, espacamento 0.12, fluxo 0.22, tremorDeRotacao 1, tremorDeTamanho 0.2, multiplicadorDeLargura 2.4, pressaoNaOpacidade 0.6.")
        appendLine("- Aerógrafo: forma REDONDA, dureza 0, espacamento 0.08, fluxo 0.07, pressaoNaOpacidade 0.8, multiplicadorDeLargura 2.6.")
        appendLine("- Giz/carvão: ponta carvao ou giz-pastel, espacamento 0.08–0.1, tremorDeRotacao 1, dispersao 0.04, granulado PAPEL 0.6–0.7 fixo no papel.")
        appendLine("- Marcador: ponta chanfrado, anguloFixo 35, espacamento 0.03, fluxo 0.9 (sobrepor escurece pouco).")
        appendLine("- Cerdas/óleo: ponta cerdas, seguirTraco true, espacamento 0.02, pressaoNoTamanho 0.6, afinamentoFim 0.3, velocidadeNaOpacidade 0.3.")
        appendLine()
        appendLine("ARMADILHAS")
        appendLine("- Espaçamento alto com ponta macia vira 'contas de colar': para traço contínuo use ≤0.08.")
        appendLine("- Fluxo muito baixo + espaçamento alto = traço quase invisível; fluxo baixo pede espaçamento baixo.")
        appendLine("- Ponta texturizada sem tremorDeRotacao mostra o mesmo desenho repetido em fila.")
        appendLine("- Cerdas sem seguirTraco ficam como uma linha de pontos parada, não como fios.")
        appendLine("- pressaoNoTamanho 1 com afinamento alto pode sumir com o traço em toque leve: teste.")
        appendLine()
        appendLine("PROCESSO")
        appendLine("1) Entenda o pedido (material, espessura, borda, textura, se reage à pressão). 2) Parta de uma receita ou de um pincel parecido (criar_pincel com base). 3) testar_pincel e OLHE a imagem. 4) Ajuste 1–3 parâmetros por vez com ajustar_pincel e teste de novo (até 3 rodadas). 5) Mostre ao usuário o resultado e ofereça usar_pincel. Nunca diga que ficou bom sem ter visto a amostra.")
        appendLine("Para recriar um traço de referência (foto anexada), descreva o que vê (borda, textura, falhas, variação de espessura) antes de escolher a ponta e os parâmetros. Para uma ponta ou textura feita de uma imagem, use usar_imagem_como_ponta com a imagem anexada (ou gere uma no Higgsfield, anexe e use).")
    }.trim()
}
